import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import { createServer } from 'vite';
const server = await createServer({configFile:false,optimizeDeps:{noDiscovery:true,entries:[]},server:{middlewareMode:true,watch:null,hmr:false,ws:false},appType:'custom'});
const checks=[];
try {
  const {buildDesign,DEFAULT_CONFIG}=await server.ssrLoadModule('/src/twin/assets/design.ts');
  const {initialize,advanceWithStep,summarize}=await server.ssrLoadModule('/src/twin/engine/simulation.ts');
  const {createWorkerHandler}=await server.ssrLoadModule('/src/twin/engine/worker.ts');
  const {identity,preflightJSON,validateStructure}=await server.ssrLoadModule('/src/twin/persistence/structure.ts');
  const {projectFile,serializeProject}=await server.ssrLoadModule('/src/twin/persistence/project.ts');
  const {allocateGrid}=await server.ssrLoadModule('/src/twin/solvers/electrical.ts');
  const d=buildDesign({...DEFAULT_CONFIG,requestedAccelerators:1280,batteryWhPerModule:1000});
  const events=[{id:'trip',timeS:1,assetId:'shore/bus',kind:'trip'},{id:'restore',timeS:8,assetId:'shore/bus',kind:'restore'}];
  const expected=advanceWithStep(d,initialize(d),12,events,.125),responses=[];
  await createWorkerHandler(r=>responses.push(r),async()=>{})({version:2,requestId:1,epoch:1,kind:'replay',design:d,events:expected.events,durationS:12,integrationStepS:expected.integrationStepS});
  assert.equal(responses.at(-1).status,'complete'); const replayed=responses.at(-1).state;replayed.solverMs=0;assert.deepEqual(replayed,expected);checks.push({name:'fractional replay exact',status:'PASS',stepS:replayed.integrationStepS,batteryWh:replayed.modules[0].batteryWh,facilityEnergyWh:replayed.facilityEnergyWh});
  const small=buildDesign({...DEFAULT_CONFIG,requestedAccelerators:8});
  const bad=structuredClone(small),state=initialize(small);bad.config.supplyW=Infinity;state.designIdentity=identity(bad);const rejected=[];
  await createWorkerHandler(r=>rejected.push(r),async()=>{})({version:2,requestId:1,epoch:1,kind:'restore',design:bad,state});assert.equal(rejected.at(-1).status,'failed');assert.equal(rejected.at(-1).state,undefined);assert.equal(rejected.at(-1).diagnostic.kind,'invalid-input');checks.push({name:'worker restore validates design',status:'PASS',diagnostic:rejected.at(-1).diagnostic.code});
  const shelf=JSON.stringify([{name:'overflow',project:projectFile(small,initialize(small))}]).replaceAll('"budgetUSD":null','"budgetUSD":1e309');
  assert.throws(()=>{preflightJSON(shelf);validateStructure(JSON.parse(shelf))},e=>e.diagnostic?.code==='INVALID_NUMBER');checks.push({name:'raw shelf overflow rejects before rewriting',status:'PASS'});
  assert.throws(()=>allocateGrid(Array(1),10,new Map()),e=>e.diagnostic?.kind==='invalid-input');checks.push({name:'sparse allocation rejected',status:'PASS'});
  const missing=structuredClone(small);missing.assets=missing.assets.filter(a=>a.id!=='shore/grid');assert.throws(()=>serializeProject(projectFile(missing,initialize(missing))),e=>e.diagnostic?.code==='DESIGN_SOURCE');checks.push({name:'missing source reference rejected',status:'PASS'});
  const units=structuredClone(small),edge=units.connections.find(c=>c.from==='shore/grid'&&c.medium==='power');units.assets.find(a=>a.id==='shore/grid').ports.find(p=>p.id===edge.fromPort).unit='bit/s';assert.throws(()=>initialize(units),e=>e.diagnostic?.code==='PORT_UNIT');checks.push({name:'connected power port unit mismatch rejected',status:'PASS'});
  for(const accelerators of [32000,32008]){const campus=buildDesign({...DEFAULT_CONFIG,requestedAccelerators:accelerators,supplyW:1e9});const summary=summarize(campus,initialize(campus));assert.equal(summary.availableAccelerators,accelerators===32000?32000:0);checks.push({name:'deferred shared network boundary',status:'PASS',accelerators,availableAccelerators:summary.availableAccelerators});}
} finally {await server.close();await fs.writeFile('artifacts/phase-1-review/recheck.json',JSON.stringify({checkedAt:new Date().toISOString(),checks},null,2)+'\n');}
console.log(JSON.stringify({status:'PASS',checks},null,2));
